```jsx
// 로그인 폼 컴포넌트 예시
import { useState } from 'react';
import { supabase } from '../lib/supabaseClient';

const LoginForm = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const handleEmailLogin = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const { error } = await supabase.auth.signInWithPassword({
        email,
        password,
      });

      if (error) throw error;
    } catch (error) {
      setError(error.message);
    } finally {
      setLoading(false);
    }
  };

  const handleKakaoLogin = async () => {
    try {
      await supabase.auth.signInWithOAuth({
        provider: 'kakao',
        options: {
          redirectTo: `${window.location.origin}/auth/callback`
        }
      });
    } catch (error) {
      setError(error.message);
    }
  };

  return (
    <div className="login-form">
      {error && <div className="error">{error}</div>}
      <form onSubmit={handleEmailLogin}>
        <input
          type="email"
          placeholder="이메일"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
        />
        <input
          type="password"
          placeholder="비밀번호"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
        />
        <button type="submit" disabled={loading}>
          {loading ? '로그인 중...' : '로그인'}
        </button>
      </form>
      <button onClick={handleKakaoLogin} className="kakao-login-btn">
        카카오로 로그인
      </button>
      <div className="links">
        <a href="/reset-password">비밀번호 찾기</a>
        <a href="/signup">회원가입</a>
      </div>
    </div>
  );
};

export default LoginForm;
```

다음 기능을 포함하는 인증 상태 관리 컨텍스트를 구현합니다:

1. AuthContext 및 AuthProvider 컴포넌트 생성
2. 사용자 인증 상태 추적 (로그인/로그아웃)
3. 로딩 상태 관리
4. 인증 관련 함수 제공:
   - 로그인 (이메일/비밀번호, 카카오)
   - 로그아웃
   - 회원가입
   - 비밀번호 재설정
5. 인증된 사용자 정보 접근 방법 제공

```jsx
// src/contexts/AuthContext.js
import { createContext, useContext, useState, useEffect } from 'react';
import { supabase } from '../lib/supabaseClient';

const AuthContext = createContext();

export const useAuth = () => {
  return useContext(AuthContext);
};

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // 초기 사용자 상태 확인
    const getInitialUser = async () => {
      const { data } = await supabase.auth.getUser();
      setUser(data?.user || null);
      setLoading(false);
    };

    getInitialUser();

    // 인증 상태 변경 리스너 설정
    const { data: authListener } = supabase.auth.onAuthStateChange(
      async (event, session) => {
        setUser(session?.user || null);
        setLoading(false);
      }
    );

    return () => {
      authListener?.subscription?.unsubscribe();
    };
  }, []);

  // 로그인 함수
  const signIn = async (email, password) => {
    try {
      const { data, error } = await supabase.auth.signInWithPassword({
        email,
        password,
      });
      if (error) throw error;
      return data;
    } catch (error) {
      throw error;
    }
  };

  // 카카오 로그인 함수
  const signInWithKakao = async () => {
    try {
      const { data, error } = await supabase.auth.signInWithOAuth({
        provider: 'kakao',
        options: {
          redirectTo: `${window.location.origin}/auth/callback`
        }
      });
      if (error) throw error;
      return data;
    } catch (error) {
      throw error;
    }
  };

  // 회원가입 함수
  const signUp = async (email, password) => {
    try {
      const { data, error } = await supabase.auth.signUp({
        email,
        password,
      });
      if (error) throw error;
      return data;
    } catch (error) {
      throw error;
    }
  };

  // 로그아웃 함수
  const signOut = async () => {
    try {
      const { error } = await supabase.auth.signOut();
      if (error) throw error;
    } catch (error) {
      throw error;
    }
  };

  // 비밀번호 재설정 이메일 전송 함수
  const resetPassword = async (email) => {
    try {
      const { error } = await supabase.auth.resetPasswordForEmail(email, {
        redirectTo: `${window.location.origin}/reset-password`,
      });
      if (error) throw error;
    } catch (error) {
      throw error;
    }
  };

  // 새 비밀번호 설정 함수
  const updatePassword = async (newPassword) => {
    try {
      const { error } = await supabase.auth.updateUser({
        password: newPassword,
      });
      if (error) throw error;
    } catch (error) {
      throw error;
    }
  };

  const value = {
    user,
    loading,
    signIn,
    signInWithKakao,
    signUp,
    signOut,
    resetPassword,
    updatePassword,
  };

  return (
    <AuthContext.Provider value={value}>
      {!loading && children}
    </AuthContext.Provider>
  );
};
```

다음 기능을 포함하는 사용자 정보 동기화 로직을 개발합니다:

1. 회원가입 시 users 테이블에 사용자 정보 저장
2. 로그인 시 사용자 정보 업데이트
3. 카카오 로그인 시 프로필 정보 동기화
4. 사용자 정보 변경 시 데이터베이스 업데이트
5. Supabase Triggers 또는 Edge Functions를 활용한 자동 동기화 설정

```jsx
// src/utils/userSync.js
import { supabase } from '../lib/supabaseClient';

// 사용자 정보 조회 함수
export const getUserProfile = async (userId) => {
  try {
    const { data, error } = await supabase
      .from('users')
      .select('*')
      .eq('id', userId)
      .single();

    if (error) throw error;
    return data;
  } catch (error) {
    console.error('사용자 정보 조회 오류:', error.message);
    throw error;
  }
};

// 사용자 정보 생성/업데이트 함수
export const upsertUserProfile = async (userData) => {
  const { id, email, user_metadata } = userData;

  try {
    const { data, error } = await supabase
      .from('users')
      .upsert({
        id,
        email,
        nickname: user_metadata?.nickname || email.split('@')[0],
        provider: user_metadata?.provider || 'email',
        avatar_url: user_metadata?.avatar_url,
        updated_at: new Date(),
      }, { onConflict: 'id' })
      .select()
      .single();

    if (error) throw error;
    return data;
  } catch (error) {
    console.error('사용자 정보 업데이트 오류:', error.message);
    throw error;
  }
};

// 인증 이벤트에 따른 사용자 정보 동기화 함수
export const syncUserOnAuth = async (event, session) => {
  if (!session?.user) return;

  const user = session.user;

  if (event === 'SIGNED_IN' || event === 'USER_UPDATED') {
    // 로그인 또는 사용자 정보 업데이트 시 동기화
    await upsertUserProfile(user);
  }
};

// 카카오 사용자 정보 처리 함수
export const processKakaoUserInfo = async (user) => {
  if (user.app_metadata.provider !== 'kakao') return user;

  // 카카오 사용자 정보 추출 및 가공
  const kakaoData = user.identities.find(identity => 
    identity.provider === 'kakao'
  )?.identity_data;

  if (kakaoData) {
    // 카카오 프로필 정보로 사용자 정보 업데이트
    await upsertUserProfile({
      id: user.id,
      email: user.email,
      user_metadata: {
        nickname: kakaoData.properties?.nickname,
        avatar_url: kakaoData.properties?.profile_image,
        provider: 'kakao'
      }
    });
  }

  return user;
};

// Supabase Trigger SQL 예시 (SQL Editor에서 실행)
/*
-- auth.users 테이블 변경 시 users 테이블 동기화 트리거
CREATE OR REPLACE FUNCTION public.handle_user_update()
RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO public.users (id, email, nickname, provider, created_at)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'nickname', split_part(NEW.email, '@', 1)),
    COALESCE(NEW.raw_app_meta_data->>'provider', 'email'),
    NEW.created_at
  )
  ON CONFLICT (id) DO UPDATE
  SET 
    email = NEW.email,
    nickname = COALESCE(NEW.raw_user_meta_data->>'nickname', split_part(NEW.email, '@', 1)),
    provider = COALESCE(NEW.raw_app_meta_data->>'provider', 'email'),
    updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE TRIGGER on_auth_user_created
  AFTER INSERT OR UPDATE ON auth.users
  FOR EACH ROW EXECUTE PROCEDURE public.handle_user_update();
*/
```

