```jsx
// 습관 목록 컴포넌트 예시
const HabitList = () => {
  const [habits, setHabits] = useState([]);
  const [loading, setLoading] = useState(true);
  const { user } = useAuth();

  useEffect(() => {
    const fetchHabits = async () => {
      try {
        setLoading(true);
        const { data, error } = await supabase
          .from('habits')
          .select('*')
          .eq('user_id', user.id)
          .order('created_at', { ascending: false });

        if (error) throw error;
        setHabits(data || []);
      } catch (error) {
        console.error('Error fetching habits:', error);
        toast.error('습관 목록을 불러오는데 실패했습니다.');
      } finally {
        setLoading(false);
      }
    };

    fetchHabits();
  }, [user]);

  return (
    <div className="habit-list-container">
      {loading ? (
        <LoadingSpinner />
      ) : habits.length > 0 ? (
        <ul>
          {habits.map((habit) => (
            <HabitItem key={habit.id} habit={habit} />
          ))}
        </ul>
      ) : (
        <EmptyState message="등록된 습관이 없습니다. 새 습관을 추가해보세요!" />
      )}
    </div>
  );
};
```

다음 기능을 구현합니다:

