2. 일일 목표 관리 기능:
   - 목표 완료 상태 업데이트 함수
   - 습관 수정 시 관련 일일 목표 업데이트 로직
   - 습관 삭제 시 관련 일일 목표 처리 방식

3. 일일 목표 데이터 동기화:
   - 오프라인 상태에서의 임시 저장 처리
   - 재접속 시 데이터 동기화 메커니즘

```jsx
// 일일 목표 자동 생성 함수 예시
const generateDailyGoals = async (habitId, frequency, startDate, duration = 30) => {
  try {
    const dailyGoals = [];
    const start = new Date(startDate);

    // 빈도에 따른 목표일 계산
    for (let i = 0; i < duration; i++) {
      const date = new Date(start);
      date.setDate(start.getDate() + i);

      // 빈도 패턴에 따라 목표 생성 여부 결정
      const shouldCreateGoal = checkFrequencyPattern(date, frequency);

      if (shouldCreateGoal) {
        dailyGoals.push({
          habit_id: habitId,
          date: date.toISOString().split('T')[0],
          completed: false
        });
      }
    }

    // 일일 목표 일괄 생성
    const { error } = await supabase
      .from('habit_daily_goals')
      .insert(dailyGoals);

    if (error) throw error;

    return dailyGoals.length;
  } catch (error) {
    console.error('Error generating daily goals:', error);
    throw error;
  }
};

// 빈도 패턴 체크 함수
const checkFrequencyPattern = (date, frequency) => {
  // 매일인 경우
  if (frequency === 'daily') return true;

  // 특정 요일인 경우 (예: ['mon', 'wed', 'fri'])
  if (Array.isArray(frequency)) {
    const dayOfWeek = date.toLocaleDateString('en-US', { weekday: 'short' }).toLowerCase();
    return frequency.includes(dayOfWeek);
  }

  // 주 n회인 경우 (추가 로직 필요)

  return false;
};
```

