// 일일 목표 체크 컴포넌트 예시
const HabitCheckItem = ({ goal, onToggle }) => {
  const [isUpdating, setIsUpdating] = useState(false);

  const handleToggle = async () => {
    try {
      setIsUpdating(true);
      await onToggle(goal.id, !goal.completed);
    } finally {
      setIsUpdating(false);
    }
  };

  return (
    <div className="habit-check-item">
      <div className="habit-info">
        <h3>{goal.habit_title}</h3>
