```jsx
// Supabase 습관 관리 서비스 예시
const habitService = {
  // 습관 목록 조회
  async getHabits(userId) {
    const { data, error } = await supabase
      .from('habits')
      .select('*')
      .eq('user_id', userId)
      .order('created_at', { ascending: false });

    if (error) throw error;
    return data;
  },

  // 습관 생성 (트랜잭션 처리)
  async createHabit(userId, habitData) {
    // Supabase에서는 트랜잭션을 직접 지원하지 않으므로 순차적 처리
    try {
      // 1. 습관 생성
      const { data: habit, error } = await supabase
        .from('habits')
        .insert([{ user_id: userId, ...habitData }])
        .select()
        .single();

      if (error) throw error;

      // 2. 일일 목표 생성
      const goalCount = await generateDailyGoals(
        habit.id, 
        habitData.frequency, 
        new Date().toISOString().split('T')[0],
        30 // 기본 30일
      );

      return { ...habit, goalCount };
    } catch (error) {
      console.error('Error in createHabit transaction:', error);
      throw error;
    }
  },

  // 습관 수정
  async updateHabit(habitId, userId, updates) {
    const { data, error } = await supabase
      .from('habits')
      .update(updates)
      .eq('id', habitId)
      .eq('user_id', userId) // RLS 정책 준수
      .select()
      .single();

    if (error) throw error;
    return data;
  },

  // 습관 삭제 (관련 일일 목표도 함께 삭제)
  async deleteHabit(habitId, userId) {
    try {
      // 1. 관련 일일 목표 삭제
      const { error: goalsError } = await supabase
        .from('habit_daily_goals')
        .delete()
        .eq('habit_id', habitId);

      if (goalsError) throw goalsError;

      // 2. 습관 삭제
      const { error } = await supabase
        .from('habits')
        .delete()
        .eq('id', habitId)
        .eq('user_id', userId); // RLS 정책 준수

      if (error) throw error;

      return true;
    } catch (error) {
      console.error('Error deleting habit:', error);
      throw error;
    }
  },

  // 실시간 구독 설정
  subscribeToHabitChanges(userId, callback) {
    return supabase
      .channel('habit-changes')
      .on('postgres_changes', {
        event: '*',
        schema: 'public',
        table: 'habits',
        filter: `user_id=eq.${userId}`
      }, callback)
      .subscribe();
  }
};
```

