// 일일 목표 체크 토글 함수 예시
const toggleDailyGoal = async (goalId, currentStatus) => {
  try {
    const newStatus = !currentStatus;

    // 낙관적 UI 업데이트를 위한 로컬 상태 변경
    setDailyGoals(prev => 
      prev.map(goal => 
        goal.id === goalId ? {...goal, completed: newStatus} : goal
      )
    );

    // 서버 상태 업데이트
    const { data, error } = await supabase
      .from('challenge_daily_goals')
      .update({ completed: newStatus })
      .eq('id', goalId)
      .select()
      .single();

    if (error) {
      // 오류 발생 시 UI 롤백
      setDailyGoals(prev => 
        prev.map(goal => 
          goal.id === goalId ? {...goal, completed: currentStatus} : goal
        )
      );
      throw error;
    }

    return data;
  } catch (error) {
    console.error('Error toggling daily goal:', error);
    throw error;
  }
};
