// 챌린지 진행 상황 데이터 조회 함수 예시
const getChallengeProgress = async (challengeId) => {
  try {
    // 1. 챌린지 참가자 조회
    const { data: participants, error: participantsError } = await supabase
      .from('challenge_participants')
      .select('user_id, users(nickname)')
      .eq('challenge_id', challengeId);

    if (participantsError) throw participantsError;

    // 2. 일일 목표 데이터 조회
    const { data: goals, error: goalsError } = await supabase
      .from('challenge_daily_goals')
      .select('user_id, date, completed')
      .eq('challenge_id', challengeId);

    if (goalsError) throw goalsError;

    // 3. 참가자별 진행 상황 계산
    const progressByUser = participants.map(participant => {
      const userGoals = goals.filter(goal => goal.user_id === participant.user_id);
      const completedGoals = userGoals.filter(goal => goal.completed);
      const completionRate = userGoals.length > 0 ? 
        (completedGoals.length / userGoals.length) * 100 : 0;

      return {
        userId: participant.user_id,
        nickname: participant.users.nickname,
        totalGoals: userGoals.length,
        completedGoals: completedGoals.length,
        completionRate: Math.round(completionRate)
      };
    });

    // 4. 전체 챌린지 진행 상황 계산
    const overallCompletionRate = progressByUser.length > 0 ?
      progressByUser.reduce((sum, user) => sum + user.completionRate, 0) / progressByUser.length : 0;

    return {
      participants: progressByUser,
      overallCompletionRate: Math.round(overallCompletionRate),
      totalParticipants: participants.length
    };
  } catch (error) {
    console.error('Error fetching challenge progress:', error);
    throw error;
  }
};
```

