```jsx
// 권한 검사 유틸리티 함수 예시
const checkChallengePermission = async (challengeId, requiredRole = 'participant') => {
  try {
    // 챌린지 정보 조회
    const { data: challenge, error: challengeError } = await supabase
      .from('challenges')
      .select('creator_id')
      .eq('id', challengeId)
      .single();

    if (challengeError) throw challengeError;

    // 생성자 권한 확인
    if (requiredRole === 'creator') {
      return challenge.creator_id === user.id;
    }

    // 참가자 권한 확인
    if (requiredRole === 'participant') {
      const { data, error } = await supabase
        .from('challenge_participants')
        .select('id')
        .match({ challenge_id: challengeId, user_id: user.id })
        .maybeSingle();

      if (error) throw error;
      return !!data;
    }

    return false;
  } catch (error) {
    console.error('Error checking challenge permission:', error);
    return false;
  }
};

// Supabase RLS 정책 예시 (SQL)
/*
-- challenges 테이블 RLS 정책
CREATE POLICY "Users can view all challenges" 
  ON challenges FOR SELECT 
  USING (true);

CREATE POLICY "Users can create challenges" 
  ON challenges FOR INSERT 
  WITH CHECK (auth.uid() = creator_id);

CREATE POLICY "Only creators can update challenges" 
  ON challenges FOR UPDATE 
  USING (auth.uid() = creator_id);

CREATE POLICY "Only creators can delete challenges" 
  ON challenges FOR DELETE 
  USING (auth.uid() = creator_id);
*/
