```jsx
// FAQ 페이지 컴포넌트 예시
const FAQPage = () => {
  const [faqGroups, setFaqGroups] = useState([]);
  const [activeGroup, setActiveGroup] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    const fetchFAQs = async () => {
      // 1. FAQ 그룹 조회
      const { data: groups, error: groupsError } = await supabase
        .from('faq_groups')
        .select('*')
        .order('sort_order');

      if (groupsError) {
        console.error('Error fetching FAQ groups:', groupsError);
        return;
      }

      // 2. 각 그룹에 속한 FAQ 항목 조회
      const groupsWithItems = await Promise.all(
        groups.map(async (group) => {
          const { data: items, error: itemsError } = await supabase
            .from('faq_items')
            .select('*')
            .eq('group_id', group.id)
            .eq('is_active', true)
            .order('sort_order');

          if (itemsError) {
            console.error(`Error fetching FAQ items for group ${group.id}:`, itemsError);
            return { ...group, items: [] };
          }

          return { ...group, items };
        })
      );

      setFaqGroups(groupsWithItems);
      if (groupsWithItems.length > 0) {
        setActiveGroup(groupsWithItems[0].id);
      }
    };

    fetchFAQs();
  }, []);

  // FAQ 항목 필터링 (검색 기능)
  const filteredGroups = faqGroups.map(group => ({
    ...group,
    items: group.items.filter(item => 
      item.question.toLowerCase().includes(searchQuery.toLowerCase()) ||
      item.answer.toLowerCase().includes(searchQuery.toLowerCase())
    )
  })).filter(group => group.items.length > 0);

  return (
    <div className="container mx-auto py-8 px-4">
      <h1 className="text-3xl font-bold mb-6">자주 묻는 질문</h1>

      {/* 검색 입력 필드 */}
      <div className="mb-6">
        <input
          type="text"
          placeholder="질문 검색..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          className="w-full p-2 border rounded"
        />
      </div>

      {/* FAQ 그룹 탭 */}
      <div className="flex flex-wrap gap-2 mb-6">
        {filteredGroups.map(group => (
          <button
            key={group.id}
            onClick={() => setActiveGroup(group.id)}
            className={`px-4 py-2 rounded ${activeGroup === group.id ? 'bg-blue-500 text-white' : 'bg-gray-200'}`}
          >
            {group.name}
          </button>
        ))}
      </div>

      {/* FAQ 아코디언 */}
      <div className="space-y-4">
        {filteredGroups
          .filter(group => activeGroup === null || group.id === activeGroup)
          .map(group => (
            <div key={group.id} className="mb-6">
              <h2 className="text-xl font-semibold mb-4">{group.name}</h2>
              {group.items.map(item => (
                <Accordion key={item.id} type="single" collapsible>
                  <AccordionItem value={`item-${item.id}`}>
                    <AccordionTrigger>{item.question}</AccordionTrigger>
                    <AccordionContent>{item.answer}</AccordionContent>
                  </AccordionItem>
                </Accordion>
              ))}
            </div>
          ))}
      </div>
    </div>
  );
};
```

