```javascript
// Supabase Edge Function 예시 (카카오톡 메시지 전송)
// filename: functions/send-kakao-message/index.js

import { createClient } from '@supabase/supabase-js';

const supabaseUrl = Deno.env.get('SUPABASE_URL');
const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
const kakaoApiKey = Deno.env.get('KAKAO_API_KEY');

const supabase = createClient(supabaseUrl, supabaseServiceKey);

export async function sendHabitReminder() {
  try {
    // 1. 오늘 완료하지 않은 습관이 있는 사용자 조회
    const today = new Date().toISOString().split('T')[0];

    const { data: incompleteGoals, error } = await supabase
      .from('habit_daily_goals')
      .select(`
        id,
        completed,
        habits!inner(title, user_id),
        users!inner(id, kakao_user_id)
      `)
      .eq('date', today)
      .eq('completed', false)
      .not('users.kakao_user_id', 'is', null);

    if (error) throw error;

    // 2. 사용자별로 그룹화
    const userReminders = {};

    incompleteGoals.forEach(goal => {
      const userId = goal.habits.user_id;
      const kakaoUserId = goal.users.kakao_user_id;

      if (!userReminders[userId]) {
        userReminders[userId] = {
          kakaoUserId,
          habits: []
        };
      }

      userReminders[userId].habits.push(goal.habits.title);
    });

    // 3. 각 사용자에게 카카오톡 메시지 전송
    for (const userId in userReminders) {
      const { kakaoUserId, habits } = userReminders[userId];

      // 메시지 생성
      const habitsList = habits.join(', ');
      const messageText = `오늘 완료하지 않은 습관이 있어요: ${habitsList}. 지금 바로 체크해보세요!`;

      // 카카오톡 메시지 API 호출
      const response = await fetch('https://kapi.kakao.com/v2/api/talk/memo/default/send', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
          'Authorization': `Bearer ${kakaoApiKey}`
        },
        body: new URLSearchParams({
          template_object: JSON.stringify({
            object_type: 'text',
            text: messageText,
            link: {
              web_url: 'https://thegreatesthabit.com/habits',
              mobile_web_url: 'https://thegreatesthabit.com/habits'
            },
            button_title: '습관 체크하기'
          })
        })
      });

      if (!response.ok) {
        const errorData = await response.json();
        console.error(`Failed to send Kakao message to user ${userId}:`, errorData);
      }
    }

    return { success: true, count: Object.keys(userReminders).length };
  } catch (error) {
    console.error('Error sending habit reminders:', error);
    return { success: false, error: error.message };
  }
}

// HTTP 엔드포인트 핸들러
Deno.serve(async (req) => {
  if (req.method === 'POST') {
    const result = await sendHabitReminder();
    return new Response(JSON.stringify(result), {
      headers: { 'Content-Type': 'application/json' }
    });
  }

  return new Response(JSON.stringify({ error: 'Method not allowed' }), {
    status: 405,
    headers: { 'Content-Type': 'application/json' }
  });
});
```

