// 카카오 메시지 전송 기본 함수
async function sendKakaoMessage(userId, messageTemplate) {
  try {
    // 사용자의 카카오 토큰 조회
    const { data: userData, error: userError } = await supabase
      .from('users')
      .select('kakao_access_token, kakao_refresh_token')
      .eq('id', userId)
      .single();

    if (userError) throw userError;

    // 토큰 유효성 확인 및 필요시 갱신
    const token = await validateAndRefreshToken(userData);

    // 카카오톡 메시지 API 호출
    const response = await fetch('https://kapi.kakao.com/v2/api/talk/memo/default/send', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        'Authorization': `Bearer ${token}`
      },
      body: new URLSearchParams({
        template_object: JSON.stringify(messageTemplate)
      })
    });

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(`Kakao API Error: ${JSON.stringify(errorData)}`);
    }

    return { success: true };
  } catch (error) {
    console.error('Error sending Kakao message:', error);
    return { success: false, error: error.message };
  }
}
