// 습관 완료 독려 메시지 함수
async function sendHabitReminders() {
  try {
    // 오늘 완료하지 않은 습관이 있는 사용자 조회
    const today = new Date().toISOString().split('T')[0];

    const { data: incompleteGoals, error } = await supabase
      .from('habit_daily_goals')
      .select(`
        id,
        habits!inner(id, title, user_id),
        users!inner(id, notification_settings)
      `)
      .eq('date', today)
      .eq('completed', false)
      .filter('users.notification_settings->habit_reminder', 'eq', true);

    if (error) throw error;

    // 사용자별로 그룹화
    const userReminders = {};

    incompleteGoals.forEach(goal => {
      const userId = goal.habits.user_id;

      if (!userReminders[userId]) {
        userReminders[userId] = {
          habits: []
        };
      }

      userReminders[userId].habits.push({
        id: goal.habits.id,
        title: goal.habits.title
      });
    });

    // 각 사용자에게 메시지 전송
    for (const userId in userReminders) {
      const { habits } = userReminders[userId];

      // 메시지 템플릿 생성
      const habitsList = habits.map(h => h.title).join(', ');
      const messageTemplate = {
        object_type: 'text',
        text: `오늘 완료하지 않은 습관이 있어요: ${habitsList}. 지금 바로 체크해보세요!`,
        link: {
          web_url: 'https://thegreatesthabit.com/habits',
          mobile_web_url: 'https://thegreatesthabit.com/habits'
        },
        button_title: '습관 체크하기'
      };

      // 메시지 전송
      await sendKakaoMessage(userId, messageTemplate);
    }

    return { success: true, count: Object.keys(userReminders).length };
  } catch (error) {
    console.error('Error sending habit reminders:', error);
    return { success: false, error: error.message };
  }
}
