```jsx
// 알림 설정 컴포넌트 예시
const NotificationSettings = () => {
  const { user } = useAuth();
  const [settings, setSettings] = useState({
    habit_reminder: true,
    challenge_reminder: true,
    achievement_notification: true,
    reminder_time: '20:00',
    frequency: 'daily'
  });
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    // 사용자 알림 설정 로드
    const loadSettings = async () => {
      setLoading(true);
      try {
        const { data, error } = await supabase
          .from('users')
          .select('notification_settings')
          .eq('id', user.id)
          .single();

        if (error) throw error;

        if (data?.notification_settings) {
          setSettings(data.notification_settings);
        }
      } catch (error) {
        console.error('Error loading notification settings:', error);
      } finally {
        setLoading(false);
      }
    };

    if (user) loadSettings();
  }, [user]);

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setSettings(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : value
    }));
  };

  const saveSettings = async () => {
    setSaving(true);
    try {
      const { error } = await supabase
        .from('users')
        .update({ notification_settings: settings })
        .eq('id', user.id);

      if (error) throw error;

      toast.success('알림 설정이 저장되었습니다.');
    } catch (error) {
      console.error('Error saving notification settings:', error);
      toast.error('알림 설정 저장에 실패했습니다.');
    } finally {
      setSaving(false);
    }
  };

  if (loading) return <div>로딩 중...</div>;

  return (
    <div className="notification-settings">
      <h2>알림 설정</h2>

      <div className="setting-group">
        <h3>알림 유형</h3>

        <div className="setting-item">
          <input
            type="checkbox"
            id="habit_reminder"
            name="habit_reminder"
            checked={settings.habit_reminder}
            onChange={handleChange}
          />
          <label htmlFor="habit_reminder">습관 완료 리마인더</label>
        </div>

        <div className="setting-item">
          <input
            type="checkbox"
            id="challenge_reminder"
            name="challenge_reminder"
            checked={settings.challenge_reminder}
            onChange={handleChange}
          />
          <label htmlFor="challenge_reminder">챌린지 참여 알림</label>
        </div>

        <div className="setting-item">
          <input
            type="checkbox"
            id="achievement_notification"
            name="achievement_notification"
            checked={settings.achievement_notification}
            onChange={handleChange}
          />
          <label htmlFor="achievement_notification">성취 축하 알림</label>
        </div>
      </div>

      <div className="setting-group">
        <h3>알림 시간</h3>

        <div className="setting-item">
          <label htmlFor="reminder_time">알림 시간:</label>
          <input
            type="time"
            id="reminder_time"
            name="reminder_time"
            value={settings.reminder_time}
            onChange={handleChange}
          />
        </div>
      </div>

      <div className="setting-group">
        <h3>알림 빈도</h3>

        <div className="setting-item">
          <select
            name="frequency"
            value={settings.frequency}
            onChange={handleChange}
          >
            <option value="daily">매일</option>
            <option value="weekdays">평일만</option>
            <option value="weekends">주말만</option>
