   - Supabase 쿼리를 통한 통계 데이터 수집
   - 클라이언트 측 데이터 가공 및 계산
   - 차트 라이브러리 (예: Chart.js, Recharts) 연동

```jsx
// 대시보드 페이지 컴포넌트 예시
import { useState, useEffect } from 'react';
import { supabase } from '../lib/supabaseClient';
import { useAuth } from '../contexts/AuthContext';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import { Card, CardContent, CardHeader, CardTitle } from '../components/ui/card';

const Dashboard = () => {
  const { user } = useAuth();
  const [loading, setLoading] = useState(true);
  const [stats, setStats] = useState({
    activeHabits: 0,
    completedToday: 0,
    totalToday: 0,
    activeChallenges: 0,
    weeklyData: []
  });

  useEffect(() => {
    const fetchDashboardData = async () => {
      try {
        setLoading(true);
        const today = new Date().toISOString().split('T')[0];

        // 1. 활성 습관 수 조회
        const { data: habits, error: habitsError } = await supabase
          .from('habits')
          .select('id')
          .eq('user_id', user.id)
          .eq('is_active', true);

        if (habitsError) throw habitsError;

        // 2. 오늘의 습관 완료율 조회
        const { data: todayGoals, error: goalsError } = await supabase
          .from('habit_daily_goals')
          .select('completed, habits!inner(user_id)')
          .eq('habits.user_id', user.id)
          .eq('date', today);

        if (goalsError) throw goalsError;

        // 3. 참여 중인 챌린지 수 조회
        const { data: challenges, error: challengesError } = await supabase
          .from('challenge_participants')
          .select('challenges!inner(id, end_date)')
          .eq('user_id', user.id)
          .gte('challenges.end_date', today);

        if (challengesError) throw challengesError;

        // 4. 주간 데이터 조회 (최근 7일)
        const weeklyData = [];
        for (let i = 6; i >= 0; i--) {
          const date = new Date();
          date.setDate(date.getDate() - i);
          const dateStr = date.toISOString().split('T')[0];

          const { data: dayGoals, error: dayGoalsError } = await supabase
            .from('habit_daily_goals')
            .select('completed, habits!inner(user_id)')
            .eq('habits.user_id', user.id)
            .eq('date', dateStr);

          if (dayGoalsError) throw dayGoalsError;

          const completed = dayGoals.filter(goal => goal.completed).length;
          const total = dayGoals.length;

          weeklyData.push({
            date: dateStr,
            day: new Date(dateStr).toLocaleDateString('ko-KR', { weekday: 'short' }),
            completed,
            total,
            completionRate: total > 0 ? Math.round((completed / total) * 100) : 0
          });
        }

        setStats({
          activeHabits: habits.length,
          completedToday: todayGoals.filter(goal => goal.completed).length,
          totalToday: todayGoals.length,
          activeChallenges: challenges.length,
          weeklyData
        });
      } catch (error) {
        console.error('Error fetching dashboard data:', error);
      } finally {
        setLoading(false);
      }
    };

    if (user) {
      fetchDashboardData();
    }
  }, [user]);

  if (loading) {
    return <div className="flex justify-center p-8">로딩 중...</div>;
  }

  return (
    <div className="container mx-auto p-4">
      <h1 className="text-3xl font-bold mb-6">대시보드</h1>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
        <Card>
          <CardHeader>
            <CardTitle>활성 습관</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-4xl font-bold">{stats.activeHabits}</div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>오늘의 완료율</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-4xl font-bold">
              {stats.totalToday > 0 
                ? `${Math.round((stats.completedToday / stats.totalToday) * 100)}%` 
                : '0%'}
            </div>
            <div className="text-sm text-gray-500">
              {stats.completedToday}/{stats.totalToday} 완료
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>참여 중인 챌린지</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-4xl font-bold">{stats.activeChallenges}</div>
          </CardContent>
        </Card>
      </div>

      <Card className="mb-8">
        <CardHeader>
          <CardTitle>주간 습관 완료율</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="h-80">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={stats.weeklyData}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="day" />
                <YAxis domain={[0, 100]} />
                <Tooltip />
                <Bar dataKey="completionRate" name="완료율 (%)" fill="#4f46e5" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </CardContent>
      </Card>

      {/* 추가 통계 및 차트 */}
    </div>
  );
};

export default Dashboard;
```

