1. Supabase 쿼리를 통한 습관 데이터 수집
   - 활성 습관 목록 조회
   - 일별/주별/월별 습관 완료 데이터 조회
   - 연속 달성 기록(스트릭) 계산

2. 챌린지 관련 데이터 수집
   - 참여 중인 챌린지 목록 조회
   - 챌린지별 진행 상황 데이터 조회
   - 챌린지 참여자 통계 조회

3. 통계 데이터 가공 및 계산
   - 완료율 계산 로직
   - 기간별 통계 집계 함수
   - 데이터 포맷팅 유틸리티 함수

```jsx
// 통계 데이터 수집 및 가공 함수 예시
export const fetchHabitStatistics = async (userId, period = 'week') => {
  try {
    // 기간에 따른 날짜 범위 계산
    const { startDate, endDate } = calculateDateRange(period);

    // 습관 데이터 조회
    const { data: habits, error: habitsError } = await supabase
      .from('habits')
      .select('id, title, is_active')
      .eq('user_id', userId)
      .eq('is_active', true);

    if (habitsError) throw habitsError;

    // 습관별 완료 데이터 조회
    const habitStats = await Promise.all(habits.map(async (habit) => {
      const { data: goals, error: goalsError } = await supabase
        .from('habit_daily_goals')
        .select('date, completed')
        .eq('habit_id', habit.id)
        .gte('date', startDate)
        .lte('date', endDate);

      if (goalsError) throw goalsError;

      // 완료율 계산
      const totalGoals = goals.length;
      const completedGoals = goals.filter(goal => goal.completed).length;
      const completionRate = totalGoals > 0 ? (completedGoals / totalGoals) * 100 : 0;

      // 연속 달성 기록(스트릭) 계산
      const streak = calculateStreak(goals);

      return {
        id: habit.id,
        title: habit.title,
        totalGoals,
        completedGoals,
        completionRate,
        streak,
        dailyData: goals
      };
    }));

    return habitStats;
  } catch (error) {
    console.error('Error fetching habit statistics:', error);
    throw error;
  }
};

// 날짜 범위 계산 함수
const calculateDateRange = (period) => {
  const endDate = new Date().toISOString().split('T')[0];
  let startDate;

  switch (period) {
    case 'week':
      const weekAgo = new Date();
      weekAgo.setDate(weekAgo.getDate() - 6);
      startDate = weekAgo.toISOString().split('T')[0];
      break;
    case 'month':
      const monthAgo = new Date();
      monthAgo.setMonth(monthAgo.getMonth() - 1);
      startDate = monthAgo.toISOString().split('T')[0];
      break;
    case 'year':
      const yearAgo = new Date();
      yearAgo.setFullYear(yearAgo.getFullYear() - 1);
      startDate = yearAgo.toISOString().split('T')[0];
      break;
    default:
      startDate = endDate; // 기본값은 오늘
  }

  return { startDate, endDate };
};

// 연속 달성 기록(스트릭) 계산 함수
const calculateStreak = (goals) => {
  // 날짜별로 정렬
  const sortedGoals = [...goals].sort((a, b) => 
    new Date(b.date) - new Date(a.date)
  );

  let currentStreak = 0;
  const today = new Date().toISOString().split('T')[0];

  // 오늘부터 역순으로 연속 달성 확인
  for (let i = 0; i < sortedGoals.length; i++) {
    const goal = sortedGoals[i];
    const goalDate = new Date(goal.date);
    const expectedDate = new Date(today);
    expectedDate.setDate(expectedDate.getDate() - i);

    // 날짜가 연속적이지 않거나 완료되지 않은 경우 중단
    if (
      goalDate.toISOString().split('T')[0] !== expectedDate.toISOString().split('T')[0] ||
      !goal.completed
    ) {
      break;
    }

    currentStreak++;
  }

  return currentStreak;
};
```

