// 기간별 습관 달성 추이 그래프 컴포넌트 예시
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Legend } from 'recharts';

const HabitTrendChart = ({ data, habits }) => {
  // 색상 배열 정의
  const colors = ['#4f46e5', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6'];

  return (
    <Card>
      <CardHeader>
        <CardTitle>습관 달성 추이</CardTitle>
      </CardHeader>
      <CardContent>
        <div className="h-80">
          <ResponsiveContainer width="100%" height="100%">
            <LineChart
              data={data}
              margin={{ top: 5, right: 30, left: 20, bottom: 5 }}
            >
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="date" />
              <YAxis domain={[0, 100]} />
              <Tooltip formatter={(value) => [`${value.toFixed(1)}%`, '완료율']} />
              <Legend />
              {habits.map((habit, index) => (
                <Line
                  key={habit.id}
                  type="monotone"
                  dataKey={`habit_${habit.id}`}
                  name={habit.title}
                  stroke={colors[index % colors.length]}
                  activeDot={{ r: 8 }}
                />
              ))}
            </LineChart>
          </ResponsiveContainer>
        </div>
      </CardContent>
    </Card>
  );
};

// 연속 달성 기록(스트릭) 캘린더 히트맵 컴포넌트 예시
import CalendarHeatmap from 'react-calendar-heatmap';
import 'react-calendar-heatmap/dist/styles.css';

const StreakCalendar = ({ data, startDate, endDate }) => {
  return (
    <Card>
      <CardHeader>
        <CardTitle>습관 달성 캘린더</CardTitle>
      </CardHeader>
      <CardContent>
        <CalendarHeatmap
          startDate={startDate}
          endDate={endDate}
          values={data}
          classForValue={(value) => {
            if (!value || value.count === 0) return 'color-empty';
            return `color-scale-${Math.min(value.count, 4)}`;
          }}
          tooltipDataAttrs={(value) => {
            if (!value || !value.date) return null;
            return {
              'data-tip': `${value.date}: ${value.count} 습관 완료`
            };
          }}
        />
        <div className="flex justify-between mt-2 text-xs text-gray-500">
          <span>적음</span>
          <div className="flex space-x-1">
            <div className="w-3 h-3 bg-[#dae5e7]"></div>
            <div className="w-3 h-3 bg-[#b5d9e2]"></div>
            <div className="w-3 h-3 bg-[#8bbfd9]"></div>
            <div className="w-3 h-3 bg-[#5ca4cf]"></div>
            <div className="w-3 h-3 bg-[#3182bd]"></div>
          </div>
          <span>많음</span>
        </div>
      </CardContent>
    </Card>
  );
};
