// 통계 페이지 컴포넌트 예시 (필터링 및 인터랙션 통합)
import { useState, useEffect } from 'react';
import { fetchHabitStatistics } from '../lib/statisticsUtils';

const StatisticsPage = () => {
  const { user } = useAuth();
  const [loading, setLoading] = useState(true);
  const [period, setPeriod] = useState('week');
  const [habits, setHabits] = useState([]);
  const [selectedHabits, setSelectedHabits] = useState([]);
  const [statsData, setStatsData] = useState(null);
  const [customDateRange, setCustomDateRange] = useState({
    startDate: null,
    endDate: null
  });

  useEffect(() => {
    const loadStatistics = async () => {
      try {
        setLoading(true);

        // 사용자의 모든 습관 조회
        const { data: habitsData } = await supabase
          .from('habits')
          .select('id, title')
          .eq('user_id', user.id)
          .eq('is_active', true);

        setHabits(habitsData || []);

        if (habitsData?.length > 0) {
          // 초기 선택은 모든 습관
          setSelectedHabits(habitsData.map(h => h.id));

          // 통계 데이터 로드
          const stats = await fetchHabitStatistics(
            user.id, 
            period,
            period === 'custom' ? customDateRange : undefined
          );

          setStatsData(stats);
        }
      } catch (error) {
        console.error('Error loading statistics:', error);
      } finally {
        setLoading(false);
      }
    };

    if (user) {
      loadStatistics();
    }
  }, [user, period, customDateRange]);

  // 필터링된 데이터 계산
  const filteredData = statsData?.filter(stat => 
    selectedHabits.includes(stat.id)
  );

  // 기간 변경 핸들러
  const handlePeriodChange = (newPeriod) => {
    setPeriod(newPeriod);
  };

  // 커스텀 날짜 범위 변경 핸들러
  const handleDateRangeChange = (range) => {
    setCustomDateRange(range);
  };

  // 데이터 내보내기 핸들러
  const handleExportCSV = () => {
    if (!filteredData) return;

    // CSV 데이터 생성 로직
    const csvContent = [
      ['습관명', '완료율', '완료 횟수', '총 횟수', '연속 달성일'],
      ...filteredData.map(stat => [
        stat.title,
        `${stat.completionRate.toFixed(1)}%`,
        stat.completedGoals,
        stat.totalGoals,
        stat.streak
      ])
    ].map(row => row.join(',')).join('\n');

    // CSV 파일 다운로드
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `습관통계_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  if (loading) {
    return <div className="flex justify-center p-8">로딩 중...</div>;
  }

  return (
    <div className="container mx-auto p-4">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold">통계</h1>
        <Button onClick={handleExportCSV}>CSV 내보내기</Button>
      </div>

      <PeriodSelector 
        currentPeriod={period} 
        onChange={handlePeriodChange} 
      />

      {period === 'custom' && (
        <DateRangePicker 
          value={customDateRange} 
          onChange={handleDateRangeChange} 
        />
      )}

      <HabitFilter 
        habits={habits} 
        selectedHabits={selectedHabits} 
        onChange={setSelectedHabits} 
      />

      {habits.length === 0 ? (
        <div className="text-center p-8 bg-gray-50 rounded-lg">
          <p className="text-gray-500">아직 등록된 습관이 없습니다.</p>
          <Button className="mt-4" asChild>
            <Link href="/habits/new">습관 만들기</Link>
          </Button>
        </div>
      ) : filteredData?.length === 0 ? (
        <div className="text-center p-8 bg-gray-50 rounded-lg">
          <p className="text-gray-500">선택한 조건에 맞는 데이터가 없습니다.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <HabitCompletionChart data={filteredData} />
          <HabitTrendChart 
            data={generateTrendData(filteredData, period)} 
            habits={filteredData.map(d => ({ id: d.id, title: d.title }))} 
          />
          <StreakCalendar 
            data={generateCalendarData(filteredData)} 
            startDate={getStartDateForPeriod(period, customDateRange)}
            endDate={new Date()}
          />
        </div>
      )}
    </div>
  );
};
