   - 계정 정보 표시 (가입일, 로그인 방식 등)

2. 알림 설정:
   - 카카오톡 알림 수신 여부 설정
   - 알림 시간대 설정
   - 알림 유형별 설정 (습관 리마인더, 챌린지 알림 등)

3. 계정 관리:
   - 비밀번호 변경 (이메일 계정만 해당)
   - 계정 연동 관리 (카카오 연결/해제)
   - 계정 삭제 기능

```jsx
// 프로필 설정 페이지 컴포넌트 예시
import { useState, useEffect } from 'react';
import { supabase } from '../lib/supabaseClient';
import { useAuth } from '../contexts/AuthContext';
import { Button } from '../components/ui/button';
import { Input } from '../components/ui/input';
import { Switch } from '../components/ui/switch';
import { Label } from '../components/ui/label';
import { Card, CardContent, CardHeader, CardTitle } from '../components/ui/card';
import { toast } from '../components/ui/toast';

const ProfileSettings = () => {
  const { user } = useAuth();
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [profile, setProfile] = useState({
    nickname: '',
    avatar_url: null
  });
  const [notifications, setNotifications] = useState({
    enabled: true,
    habit_reminder: true,
    challenge_reminder: true,
    achievement: true,
    reminder_time: '20:00'
  });

  useEffect(() => {
    const fetchProfile = async () => {
      try {
        setLoading(true);

        // 사용자 프로필 정보 조회
        const { data, error } = await supabase
          .from('users')
          .select('nickname, avatar_url, notification_settings')
          .eq('id', user.id)
          .single();

        if (error) throw error;

        setProfile({
          nickname: data.nickname || '',
          avatar_url: data.avatar_url
        });

        if (data.notification_settings) {
          setNotifications(data.notification_settings);
        }
      } catch (error) {
        console.error('Error fetching profile:', error);
        toast({
          title: '오류',
          description: '프로필 정보를 불러오는 중 오류가 발생했습니다.',
          variant: 'destructive'
        });
      } finally {
        setLoading(false);
      }
    };

    if (user) {
      fetchProfile();
    }
  }, [user]);

  const updateProfile = async () => {
    try {
      setLoading(true);

      const { error } = await supabase
        .from('users')
        .update({
          nickname: profile.nickname,
          notification_settings: notifications
        })
        .eq('id', user.id);

      if (error) throw error;

      toast({
        title: '성공',
        description: '프로필 정보가 업데이트되었습니다.'
      });
    } catch (error) {
      console.error('Error updating profile:', error);
      toast({
        title: '오류',
        description: '프로필 업데이트 중 오류가 발생했습니다.',
        variant: 'destructive'
      });
    } finally {
      setLoading(false);
    }
  };

  const uploadAvatar = async (event) => {
    try {
      setUploading(true);

      if (!event.target.files || event.target.files.length === 0) {
        return;
      }

      const file = event.target.files[0];
      const fileExt = file.name.split('.').pop();
      const filePath = `avatars/${user.id}-${Math.random().toString(36).substring(2)}.${fileExt}`;

      // 파일 업로드
      const { error: uploadError } = await supabase.storage
        .from('user-content')
        .upload(filePath, file);

      if (uploadError) throw uploadError;

      // 프로필 업데이트
      const { error: updateError } = await supabase
        .from('users')
        .update({
          avatar_url: filePath
        })
        .eq('id', user.id);

      if (updateError) throw updateError;

      // 상태 업데이트
      setProfile({
        ...profile,
        avatar_url: filePath
      });

      toast({
        title: '성공',
        description: '프로필 이미지가 업데이트되었습니다.'
      });
    } catch (error) {
      console.error('Error uploading avatar:', error);
      toast({
        title: '오류',
        description: '이미지 업로드 중 오류가 발생했습니다.',
        variant: 'destructive'
      });
    } finally {
      setUploading(false);
    }
  };

  if (loading && !profile.nickname) {
    return <div className="flex justify-center p-8">로딩 중...</div>;
  }

  return (
    <div className="container mx-auto p-4">
      <h1 className="text-3xl font-bold mb-6">프로필 설정</h1>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <Card>
          <CardHeader>
            <CardTitle>기본 정보</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div>
              <Label htmlFor="nickname">닉네임</Label>
              <Input
                id="nickname"
                value={profile.nickname}
                onChange={(e) => setProfile({ ...profile, nickname: e.target.value })}
                placeholder="닉네임을 입력하세요"
              />
            </div>

            <div>
              <Label htmlFor="avatar">프로필 이미지</Label>
              <div className="flex items-center gap-4 mt-2">
                {profile.avatar_url && (
                  <img
                    src={`${supabase.storage.from('user-content').getPublicUrl(profile.avatar_url).data.publicUrl}`}
                    alt="프로필"
                    className="w-16 h-16 rounded-full object-cover"
                  />
                )}
                <Input
                  id="avatar"
                  type="file"
                  accept="image/*"
                  onChange={uploadAvatar}
                  disabled={uploading}
                />
              </div>
            </div>

            <Button onClick={updateProfile} disabled={loading || uploading}>
              저장하기
            </Button>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>알림 설정</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="flex items-center justify-between">
              <Label htmlFor="notifications-enabled">알림 사용</Label>
              <Switch
                id="notifications-enabled"
                checked={notifications.enabled}
                onCheckedChange={(checked) => setNotifications({ ...notifications, enabled: checked })}
              />
            </div>

            <div className="flex items-center justify-between">
              <Label htmlFor="habit-reminder">습관 리마인더</Label>
              <Switch
                id="habit-reminder"
                checked={notifications.habit_reminder}
                onCheckedChange={(checked) => setNotifications({ ...notifications, habit_reminder: checked })}
                disabled={!notifications.enabled}
              />
            </div>

            <div className="flex items-center justify-between">
              <Label htmlFor="challenge-reminder">챌린지 알림</Label>
              <Switch
                id="challenge-reminder"
                checked={notifications.challenge_reminder}
                onCheckedChange={(checked) => setNotifications({ ...notifications, challenge_reminder: checked })}
                disabled={!notifications.enabled}
              />
            </div>

            <div className="flex items-center justify-between">
              <Label htmlFor="achievement">성취 축하 알림</Label>
              <Switch
                id="achievement"
                checked={notifications.achievement}
                onCheckedChange={(checked) => setNotifications({ ...notifications, achievement: checked })}
                disabled={!notifications.enabled}
              />
            </div>

            <div>
              <Label htmlFor="reminder-time">알림 시간</Label>
              <Input
                id="reminder-time"
                type="time"
                value={notifications.reminder_time}
                onChange={(e) => setNotifications({ ...notifications, reminder_time: e.target.value })}
                disabled={!notifications.enabled}
              />
            </div>

            <Button onClick={updateProfile} disabled={loading}>
              저장하기
            </Button>
          </CardContent>
        </Card>
      </div>
    </div>
  );
};

export default ProfileSettings;
```

