// 프로필 이미지 업로드 컴포넌트 예시
const ProfileImageUpload = ({ userId, currentImageUrl, onImageUpdate }) => {
  const [uploading, setUploading] = useState(false);
  const [preview, setPreview] = useState(currentImageUrl);

  const handleFileChange = async (event) => {
    try {
      const file = event.target.files[0];
      if (!file) return;

      // 파일 유효성 검사
      if (!file.type.startsWith('image/')) {
        toast({
          title: '오류',
          description: '이미지 파일만 업로드 가능합니다.',
          variant: 'destructive'
        });
        return;
      }

      // 파일 크기 제한 (2MB)
      if (file.size > 2 * 1024 * 1024) {
        toast({
          title: '오류',
          description: '파일 크기는 2MB 이하여야 합니다.',
          variant: 'destructive'
        });
        return;
      }

      // 미리보기 생성
      const reader = new FileReader();
      reader.onload = (e) => setPreview(e.target.result);
      reader.readAsDataURL(file);

      // 파일 업로드 처리
      setUploading(true);
      const fileExt = file.name.split('.').pop();
      const filePath = `avatars/${userId}-${Math.random().toString(36).substring(2)}.${fileExt}`;

      const { error: uploadError } = await supabase.storage
        .from('user-content')
        .upload(filePath, file);

      if (uploadError) throw uploadError;

      // 업로드 성공 시 콜백 호출
      onImageUpdate(filePath);

      toast({
        title: '성공',
        description: '프로필 이미지가 업데이트되었습니다.'
      });
    } catch (error) {
      console.error('Error uploading image:', error);
      toast({
        title: '오류',
        description: '이미지 업로드 중 오류가 발생했습니다.',
        variant: 'destructive'
      });
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col items-center gap-4">
        {preview && (
          <div className="relative w-24 h-24 rounded-full overflow-hidden">
            <img 
              src={preview.startsWith('data:') ? preview : `${supabase.storage.from('user-content').getPublicUrl(preview).data.publicUrl}`}
              alt="프로필"
              className="w-full h-full object-cover"
            />
          </div>
        )}
        <div className="flex items-center gap-2">
          <Input
            type="file"
            accept="image/*"
            onChange={handleFileChange}
            disabled={uploading}
            className="max-w-xs"
          />
          {uploading && <span className="text-sm text-muted-foreground">업로드 중...</span>}
        </div>
      </div>
    </div>
  );
};
