      } finally {
        setLoading(false);
      }
    };

    fetchNotificationSettings();
  }, [userId]);

  // 알림 설정 저장
  const saveSettings = async () => {
    try {
      setLoading(true);

      const { error } = await supabase
        .from('users')
        .update({
          notification_settings: settings
        })
        .eq('id', userId);

      if (error) throw error;

      toast({
        title: '성공',
