        description: '알림 설정 저장 중 오류가 발생했습니다.',
        variant: 'destructive'
      });
    } finally {
      setLoading(false);
    }
  };

  // 카카오톡 알림 연동 설정
  const connectKakaoNotifications = async () => {
    // 카카오 알림 연동 로직 구현
    // 카카오 API를 통한 메시지 수신 동의 처리
  };

  return (
    <Card>
      <CardHeader>
        <CardTitle>알림 설정</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="flex items-center justify-between">
          <Label htmlFor="notifications-enabled">알림 사용</Label>
          <Switch
            id="notifications-enabled"
            checked={settings.enabled}
            onCheckedChange={(checked) => setSettings({ ...settings, enabled: checked })}
          />
        </div>

        <div className="flex items-center justify-between">
          <Label htmlFor="habit-reminder">습관 리마인더</Label>
          <Switch
            id="habit-reminder"
            checked={settings.habit_reminder}
            onCheckedChange={(checked) => setSettings({ ...settings, habit_reminder: checked })}
            disabled={!settings.enabled}
          />
        </div>

        <div className="flex items-center justify-between">
          <Label htmlFor="challenge-reminder">챌린지 알림</Label>
          <Switch
            id="challenge-reminder"
            checked={settings.challenge_reminder}
            onCheckedChange={(checked) => setSettings({ ...settings, challenge_reminder: checked })}
            disabled={!settings.enabled}
