        <div className="flex items-center justify-between">
          <Label htmlFor="achievement">성취 축하 알림</Label>
          <Switch
            id="achievement"
            checked={settings.achievement}
            onCheckedChange={(checked) => setSettings({ ...settings, achievement: checked })}
            disabled={!settings.enabled}
          />
        </div>

        <div className="flex items-center justify-between">
          <Label htmlFor="kakao-enabled">카카오톡 알림</Label>
