다음 기능을 구현합니다:

1. 비밀번호 변경 기능 (이메일 계정만 해당):
   - 현재 비밀번호 확인
   - 새 비밀번호 입력 및 확인
   - 비밀번호 강도 검사 및 피드백
   - Supabase Auth API를 통한 비밀번호 변경 처리

2. 계정 연동 관리:
   - 카카오 계정 연결/해제 기능
   - 연동 상태 표시
   - 소셜 로그인 제공자 추가 시 확장 가능한 구조 설계

3. 계정 삭제 기능:
   - 계정 삭제 전 확인 절차
   - 사용자 데이터 처리 방식 안내
   - Supabase에서 사용자 데이터 삭제 처리
   - 삭제 후 로그아웃 및 리디렉션

```jsx
// 계정 관리 컴포넌트 예시
const AccountManagement = () => {
  const { user, signOut } = useAuth();
  const router = useRouter();

  // 비밀번호 변경 상태
  const [passwordForm, setPasswordForm] = useState({
    currentPassword: '',
    newPassword: '',
    confirmPassword: ''
  });
  const [passwordError, setPasswordError] = useState('');
  const [passwordLoading, setPasswordLoading] = useState(false);

  // 계정 연동 상태
  const [providers, setProviders] = useState({
    kakao: false
  });
  const [providerLoading, setProviderLoading] = useState(false);

  // 계정 삭제 상태
  const [deleteConfirm, setDeleteConfirm] = useState('');
  const [deleteLoading, setDeleteLoading] = useState(false);

  // 계정 정보 로드
  useEffect(() => {
    const loadUserProviders = async () => {
      try {
        const { data, error } = await supabase.auth.getUser();
        if (error) throw error;

        // 연결된 제공자 확인
        const identities = data.user.identities || [];
        setProviders({
          kakao: identities.some(identity => identity.provider === 'kakao')
        });
      } catch (error) {
        console.error('Error loading user providers:', error);
      }
    };

    if (user) {
      loadUserProviders();
    }
  }, [user]);

  // 비밀번호 변경 처리
  const handlePasswordChange = async (e) => {
    e.preventDefault();
    setPasswordError('');

    // 입력 검증
    if (passwordForm.newPassword !== passwordForm.confirmPassword) {
      setPasswordError('새 비밀번호가 일치하지 않습니다.');
      return;
    }

    if (passwordForm.newPassword.length < 8) {
      setPasswordError('비밀번호는 8자 이상이어야 합니다.');
      return;
    }

    try {
      setPasswordLoading(true);

      // Supabase 비밀번호 변경 API 호출
      const { error } = await supabase.auth.updateUser({
        password: passwordForm.newPassword
      });

      if (error) throw error;

      // 성공 메시지
      toast({
        title: '성공',
        description: '비밀번호가 변경되었습니다.'
      });

      // 폼 초기화
      setPasswordForm({
        currentPassword: '',
        newPassword: '',
        confirmPassword: ''
      });
    } catch (error) {
      console.error('Error changing password:', error);
      setPasswordError(error.message || '비밀번호 변경 중 오류가 발생했습니다.');
    } finally {
      setPasswordLoading(false);
    }
  };

  // 카카오 계정 연결
  const connectKakao = async () => {
    try {
      setProviderLoading(true);

      // Supabase OAuth 연결 API 호출
      const { error } = await supabase.auth.linkAccount({
        provider: 'kakao'
      });

      if (error) throw error;

      // 성공 메시지
      toast({
        title: '성공',
        description: '카카오 계정이 연결되었습니다.'
      });

      // 상태 업데이트
      setProviders({ ...providers, kakao: true });
    } catch (error) {
      console.error('Error connecting Kakao account:', error);
      toast({
        title: '오류',
        description: '카카오 계정 연결 중 오류가 발생했습니다.',
        variant: 'destructive'
      });
    } finally {
      setProviderLoading(false);
    }
  };

  // 카카오 계정 연결 해제
  const disconnectKakao = async () => {
    try {
      setProviderLoading(true);

      // Supabase OAuth 연결 해제 API 호출
      const { error } = await supabase.auth.unlinkAccount({
        provider: 'kakao'
      });

      if (error) throw error;

      // 성공 메시지
      toast({
        title: '성공',
        description: '카카오 계정 연결이 해제되었습니다.'
      });

      // 상태 업데이트
      setProviders({ ...providers, kakao: false });
    } catch (error) {
      console.error('Error disconnecting Kakao account:', error);
      toast({
        title: '오류',
        description: '카카오 계정 연결 해제 중 오류가 발생했습니다.',
        variant: 'destructive'
      });
    } finally {
      setProviderLoading(false);
    }
  };

  // 계정 삭제 처리
  const handleAccountDelete = async () => {
    // 확인 문구 검증
    if (deleteConfirm !== '계정 삭제') {
      toast({
        title: '오류',
        description: '확인 문구가 일치하지 않습니다.',
        variant: 'destructive'
      });
      return;
    }

    try {
      setDeleteLoading(true);

      // 사용자 데이터 삭제
      const { error: dataError } = await supabase
        .from('users')
        .delete()
        .eq('id', user.id);

      if (dataError) throw dataError;

      // Supabase 계정 삭제
      const { error: authError } = await supabase.auth.admin.deleteUser(user.id);

      if (authError) throw authError;

      // 로그아웃 처리
      await signOut();

      // 홈으로 리디렉션
      router.push('/');

      // 성공 메시지
      toast({
        title: '계정 삭제 완료',
        description: '계정이 성공적으로 삭제되었습니다.'
      });
    } catch (error) {
      console.error('Error deleting account:', error);
      toast({
        title: '오류',
        description: '계정 삭제 중 오류가 발생했습니다.',
        variant: 'destructive'
      });
    } finally {
      setDeleteLoading(false);
    }
  };

  // 이메일 계정인지 확인
  const isEmailAccount = user?.app_metadata?.provider === 'email';

  return (
    <div className="space-y-8">
      {/* 비밀번호 변경 섹션 */}
      {isEmailAccount && (
        <Card>
          <CardHeader>
            <CardTitle>비밀번호 변경</CardTitle>
          </CardHeader>
          <CardContent>
            <form onSubmit={handlePasswordChange} className="space-y-4">
              <div>
                <Label htmlFor="current-password">현재 비밀번호</Label>
                <Input
                  id="current-password"
                  type="password"
                  value={passwordForm.currentPassword}
                  onChange={(e) => setPasswordForm({ ...passwordForm, currentPassword: e.target.value })}
                  required
                />
              </div>

              <div>
                <Label htmlFor="new-password">새 비밀번호</Label>
                <Input
                  id="new-password"
                  type="password"
                  value={passwordForm.newPassword}
                  onChange={(e) => setPasswordForm({ ...passwordForm, newPassword: e.target.value })}
                  required
                />
              </div>

              <div>
                <Label htmlFor="confirm-password">새 비밀번호 확인</Label>
                <Input
                  id="confirm-password"
                  type="password"
                  value={passwordForm.confirmPassword}
                  onChange={(e) => setPasswordForm({ ...passwordForm, confirmPassword: e.target.value })}
                  required
                />
              </div>

              {passwordError && (
                <p className="text-sm text-red-500">{passwordError}</p>
              )}

              <Button type="submit" disabled={passwordLoading}>
                {passwordLoading ? '변경 중...' : '비밀번호 변경'}
              </Button>
            </form>
          </CardContent>
        </Card>
      )}

      {/* 계정 연동 섹션 */}
      <Card>
        <CardHeader>
          <CardTitle>계정 연동 관리</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <div>
                <h4 className="font-medium">카카오 계정</h4>
                <p className="text-sm text-muted-foreground">
                  {providers.kakao ? '연결됨' : '연결되지 않음'}
                </p>
              </div>
              <Button
                variant={providers.kakao ? 'destructive' : 'default'}
                onClick={providers.kakao ? disconnectKakao : connectKakao}
                disabled={providerLoading}
              >
                {providerLoading
                  ? '처리 중...'
                  : providers.kakao
                    ? '연결 해제'
                    : '연결하기'}
              </Button>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* 계정 삭제 섹션 */}
      <Card>
        <CardHeader>
          <CardTitle>계정 삭제</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-4">
            <p className="text-sm text-muted-foreground">
              계정을 삭제하면 모든 데이터가 영구적으로 제거됩니다. 이 작업은 되돌릴 수 없습니다.
            </p>

            <div>
              <Label htmlFor="delete-confirm">
                계정을 삭제하려면 <span className="font-bold">계정 삭제</span>를 입력하세요
              </Label>
              <Input
                id="delete-confirm"
                value={deleteConfirm}
                onChange={(e) => setDeleteConfirm(e.target.value)}
                className="mt-1"
              />
            </div>

            <Button
              variant="destructive"
              onClick={handleAccountDelete}
              disabled={deleteConfirm !== '계정 삭제' || deleteLoading}
            >
              {deleteLoading ? '삭제 중...' : '계정 영구 삭제'}
            </Button>
          </div>
        </CardContent>
      </Card>
    </div>
  );
};
